import type { PluginGeneratedTableSource, TypeSourceInfoEntry } from "./types";

/**
 * Checks if a table source is generated by a plugin.
 * @param source - The table source entry to check.
 * @returns True if the source was generated by a plugin.
 */
export function isPluginGeneratedTable(
  source: TypeSourceInfoEntry,
): source is PluginGeneratedTableSource {
  return source.pluginId !== undefined;
}
